-- Новые вопросы тем 01–04 (близко к лекциям и демонстрациям курса DBA1) с пояснениями к каждому варианту.
-- Повторный запуск безопасен: вопрос с тем же текстом не добавляется второй раз.

BEGIN;

INSERT INTO questions (category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM (
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какой каталог установки использует configure по умолчанию при сборке из исходных кодов?', '{"A":"`/opt/postgres`","B":"`/usr/local/pgsql`","C":"`/var/lib/postgresql`","D":"`/usr/lib/postgresql`"}'::jsonb, 'B', 'Обычно каталог установки доступен для записи только суперпользователю ОС, поэтому в демонстрации курса задают свой через --prefix.', '{"A":"Такого значения по умолчанию нет; так можно указать только явно через --prefix.","B":"Значение по умолчанию; другой каталог задаётся ключом --prefix.","C":"Это каталог данных кластеров в пакете Ubuntu, а не каталог установки программ.","D":"Здесь лежат программы PostgreSQL в пакете Ubuntu, а не при сборке из исходных кодов."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Допишите команду, которую нужно выполнить в каталоге исходных кодов перед повторной сборкой с другими параметрами configure:
```
make ___
```', '{"A":"`uninstall`","B":"`check`","C":"`distclean`","D":"`install-world`"}'::jsonb, 'C', 'Без очистки остатки предыдущей сборки могут смешаться с новыми параметрами.', '{"A":"Удаляет установленные файлы, но не результаты прошлой сборки и конфигурации.","B":"Запускает регрессионные тесты собранного сервера.","C":"Удаляет и собранные файлы, и результаты прошлого запуска configure.","D":"Устанавливает сервер вместе с расширениями и документацией после make world."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Сервер собран командами make и make install. Как собрать и установить расширения из contrib?', '{"A":"Ничего не нужно: make уже собрал все расширения","B":"Выполнить initdb с ключом --contrib","C":"Выполнить CREATE EXTENSION до сборки","D":"Выполнить make и make install в подкаталоге contrib"}'::jsonb, 'D', 'Если собирать make world, всё вместе устанавливается командой make install-world.', '{"A":"make не собирает расширения из contrib и документацию; их собирает make world.","B":"Такого ключа нет: initdb создаёт кластер и ничего не собирает.","C":"CREATE EXTENSION работает только с уже собранным и установленным расширением.","D":"Так и делается: расширения собираются отдельно от сервера."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какие библиотеки PostgreSQL использует для сжатия данных?', '{"A":"zstd","B":"readline","C":"zlib","D":"lz4"}'::jsonb, 'ACD', 'Все эти библиотеки используются, но их можно отключить при сборке.', '{"A":"Используется для сжатия; при сборке её можно отключить.","B":"Отвечает за редактирование командной строки и историю в psql, а не за сжатие.","C":"Используется для сжатия; при сборке её можно отключить.","D":"Используется для сжатия; при сборке её можно отключить."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Для чего нужна библиотека readline?', '{"A":"Для редактирования командной строки, истории и автодополнения в psql","B":"Для шифрования соединений","C":"Для кроссплатформенной поддержки Unicode","D":"Для сжатия данных"}'::jsonb, 'A', 'Это одна из библиотек, которые используются по умолчанию, но могут быть отключены при сборке.', '{"A":"В серверной установке может быть не нужна, если psql в консоли не запускают.","B":"Шифрование обеспечивает OpenSSL.","C":"Для этого используется библиотека ICU.","D":"Для сжатия служат zlib, lz4 и zstd."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Почему для сборки из репозитория git нужны Flex и Bison, а для сборки из архива с исходными кодами нет?', '{"A":"Сборка из git использует другой компилятор","B":"При сборке из архива лексический анализатор не собирается","C":"В архиве уже есть сгенерированные ими файлы на C","D":"Flex и Bison входят в архив как готовые программы"}'::jsonb, 'C', 'Поэтому сборка из git требует более широкого набора инструментов.', '{"A":"Компилятор C тот же; разница только в сгенерированных файлах.","B":"Анализатор нужен всегда, просто в архиве его код уже сгенерирован.","C":"В git хранятся исходники для Flex и Bison, а в архиве — уже готовые файлы на C.","D":"Программы в архив не входят — входят сгенерированные ими файлы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какая утилита показывает параметры, с которыми был собран PostgreSQL?', '{"A":"`pg_controldata`","B":"`psql --version`","C":"`pg_lsclusters`","D":"`pg_config`"}'::jsonb, 'D', 'Также pg_config --sysconfdir показывает каталог системного скрипта psqlrc.', '{"A":"Показывает служебную информацию управляющего файла кластера, а не параметры сборки.","B":"Показывает только версию клиента psql.","C":"Показывает список кластеров в Ubuntu, а не параметры сборки.","D":"Например, pg_config --configure выводит параметры configure."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Где в пакете Ubuntu находится каталог данных кластера main версии 16?', '{"A":"`/var/log/postgresql`","B":"`/etc/postgresql/16/main`","C":"`/var/lib/postgresql/16/main`","D":"`/usr/lib/postgresql/16`"}'::jsonb, 'C', 'Пакет размещает файлы по правилам, принятым в Ubuntu.', '{"A":"Здесь находится журнал сообщений сервера.","B":"Здесь лежат файлы конфигурации кластера.","C":"Владелец каталога — пользователь ОС postgres.","D":"Здесь лежат программы сервера, их владелец — root."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Где в пакете Ubuntu находятся файлы конфигурации кластера main версии 16?', '{"A":"`/var/lib/postgresql/16/main`","B":"`/usr/lib/postgresql/16/bin`","C":"`/etc/postgresql/16/main`","D":"`/etc/postgresql-common`"}'::jsonb, 'C', 'В отличие от сборки из исходных кодов, пакет хранит postgresql.conf вне PGDATA.', '{"A":"Это каталог данных; здесь лежит только postgresql.auto.conf.","B":"Здесь лежат программы сервера.","C":"Сервер узнаёт путь из параметра config_file, переданного при запуске.","D":"Здесь общие настройки пакетов, в том числе системный psqlrc, но не конфигурация кластера."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какая утилита пакета Ubuntu выводит список кластеров с версией, портом и состоянием?', '{"A":"`pg_isready`","B":"`pg_config`","C":"`pg_ctlcluster 16 main status`","D":"`pg_lsclusters`"}'::jsonb, 'D', 'Утилиты pg_lsclusters, pg_createcluster, pg_dropcluster и pg_ctlcluster специфичны для Ubuntu.', '{"A":"Только проверяет, принимает ли сервер подключения.","B":"Показывает параметры сборки PostgreSQL.","C":"Показывает состояние одного указанного кластера, а не список.","D":"Показывает версию, имя, порт, состояние, владельца, каталог данных и журнал."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какая утилита пакета Ubuntu удаляет кластер баз данных?', '{"A":"`pg_ctlcluster 16 main drop`","B":"`pg_dropcluster`","C":"`dropdb`","D":"`initdb --remove`"}'::jsonb, 'B', 'В других системах кластер создают initdb и удаляют средствами ОС.', '{"A":"У pg_ctlcluster нет такой команды: она запускает, останавливает и перечитывает конфигурацию.","B":"Парная к pg_createcluster утилита пакета Ubuntu.","C":"Удаляет одну базу данных внутри кластера, а не сам кластер.","D":"Такого ключа нет: initdb только создаёт кластеры."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Какие команды можно передать утилите pg_ctlcluster в Ubuntu?', '{"A":"`createdb`","B":"`start`","C":"`reload`","D":"`restart`"}'::jsonb, 'BCD', 'pg_ctlcluster — обёртка над pg_ctl: ей передают версию, имя кластера и команду.', '{"A":"Базы данных создаёт отдельная утилита createdb или команда CREATE DATABASE.","B":"Запускает сервер указанного кластера.","C":"Просит сервер перечитать файлы конфигурации.","D":"Перезапускает сервер указанного кластера."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Что верно для PostgreSQL как сервиса у облачного провайдера (DBaaS)?', '{"A":"Администратор получает полный доступ к экземпляру","B":"Резервное копирование в таком режиме невозможно","C":"Управление ограничено инструментами, которые даёт провайдер","D":"Основное администрирование берёт на себя провайдер"}'::jsonb, 'CD', 'Особенности конкретных облачных решений нужно изучать в документации провайдера.', '{"A":"Полный доступ есть, когда PostgreSQL установлен в собственной виртуальной машине.","B":"Оно выполняется предоставленными провайдером инструментами.","C":"Например, для мониторинга, резервного копирования и восстановления.","D":"В этом смысл managed database."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '01.'), 'Допишите команду, чтобы собранный сервер по умолчанию использовал порт 5555:
```
./configure --prefix=/home/student/pgsql16 ___=5555
```', '{"A":"`--pgport`","B":"`-p`","C":"`--port`","D":"`--with-pgport`"}'::jsonb, 'D', 'Порт по умолчанию — 5432, в демонстрации курса его меняют, чтобы не пересечься с установленным пакетом.', '{"A":"Такого ключа у configure нет.","B":"Такого ключа у configure нет; -p есть у psql и pg_ctl.","C":"Такого ключа у configure нет.","D":"Задаёт порт по умолчанию для собираемого сервера и клиентов."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Какими командами можно выйти из psql?', '{"A":"`\\q`","B":"`\\c`","C":"`\\x`","D":"`exit`"}'::jsonb, 'AD', 'Команды psql начинаются с обратной косой черты, но exit и quit работают без неё.', '{"A":"Основная команда выхода.","B":"Открывает новое подключение, не покидая psql.","C":"Переключает расширенный формат вывода.","D":"Альтернатива \\q, как и quit."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Что делает команда \x?', '{"A":"Включает или выключает расширенный формат вывода для следующих запросов","B":"Выполняет запрос с расширенным выводом только один раз","C":"Завершает работу psql","D":"Направляет вывод в файл"}'::jsonb, 'A', 'Повторный вызов \x возвращает обычный формат.', '{"A":"Удобно, когда у записи много столбцов.","B":"Это делает \\gx в конце запроса.","C":"Это команда \\q.","D":"Это команда \\o."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Что переключает команда \t?', '{"A":"Выравнивание значений по столбцам","B":"Транзакционный режим сеанса","C":"Вывод длительности выполнения команд","D":"Вывод строки заголовка и итоговой строки"}'::jsonb, 'D', 'Вместе \t и \a удобны для вывода, пригодного для скриптов.', '{"A":"Это делает \\a.","B":"Транзакциями управляют BEGIN, COMMIT и переменная AUTOCOMMIT.","C":"Это делает \\timing.","D":"В режиме tuples only выводятся только строки результата."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Допишите команду, чтобы задать переменную окружения ОС прямо из psql:
```
\___ HELLO Hello
```', '{"A":"`set`","B":"`getenv`","C":"`export`","D":"`setenv`"}'::jsonb, 'D', 'Проверить можно командой \! echo $HELLO.', '{"A":"Задаёт переменную psql, а не переменную окружения ОС.","B":"Читает переменную окружения в переменную psql.","C":"Это команда оболочки ОС, а не psql.","D":"Задаёт переменную окружения, видимую командам ОС, запускаемым из psql."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Допишите команду, чтобы записать значение переменной окружения USER в переменную psql User:
```
\___ User USER
```', '{"A":"`getenv`","B":"`set`","C":"`echo`","D":"`setenv`"}'::jsonb, 'A', 'Подставить значение затем можно как :User.', '{"A":"Копирует значение переменной окружения в переменную psql.","B":"Присвоит переменной User строку USER, а не значение переменной окружения.","C":"Только выводит текст на экран.","D":"Задаёт переменную окружения ОС, а не читает её."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Допишите команду, чтобы вывести TRUE или FALSE в зависимости от того, определена ли переменная psql working_dir:
```
\echo :___
```', '{"A":"`?working_dir`","B":"`{working_dir}`","C":"`{?working_dir}`","D":"`working_dir`"}'::jsonb, 'C', 'Эту проверку используют в условных конструкциях \if ... \else ... \endif.', '{"A":"Такая форма не распознаётся и будет выведена как текст.","B":"Такая форма не распознаётся и будет выведена как текст.","C":"Форма :{?имя} возвращает логическое значение: определена ли переменная.","D":"Подставит значение переменной, а если её нет, выведет текст :working_dir."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Какую переменную окружения проверяет psql, чтобы выбрать программу постраничного просмотра только для себя, не меняя её для других программ?', '{"A":"`PGPAGER`","B":"`PSQL_LESS`","C":"`PSQL_PAGER`","D":"`PGVIEWER`"}'::jsonb, 'C', 'Её удобно задать в ~/.psqlrc командой \setenv, например less -XS.', '{"A":"Такой переменной psql не использует.","B":"Такой переменной psql не использует.","C":"Если она не задана, psql использует общую переменную PAGER.","D":"Такой переменной psql не использует."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Какая переменная psql задаёт приглашение для второй и следующих строк запроса?', '{"A":"`PROMPT3`","B":"`PROMPT1`","C":"`PROMPT2`","D":"`PROMPT_CONT`"}'::jsonb, 'C', 'У PROMPT1 и PROMPT2 одинаковое значение по умолчанию, но их можно задать по-разному.', '{"A":"Приглашение при вводе данных для COPY FROM STDIN.","B":"Приглашение для первой строки запроса.","C":"Используется, пока запрос продолжается на следующих строках.","D":"Такой переменной в psql нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Какие команды psql меняют формат вывода результатов запросов?', '{"A":"`\\pset`","B":"`\\i`","C":"`\\x`","D":"`\\a`"}'::jsonb, 'ACD', 'Формат с выравниванием используется по умолчанию.', '{"A":"Даёт доступ ко всем настройкам форматирования, без параметров показывает их.","B":"Выполняет команды из файла, формат вывода не меняет.","C":"Переключает расширенный формат.","D":"Переключает вывод с выравниванием и без него."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Что делает команда psql \! pwd?', '{"A":"Повторяет последний запрос","B":"Отменяет текущую транзакцию","C":"Выполняет команду операционной системы pwd","D":"Выводит историю команд"}'::jsonb, 'C', 'Так из psql можно, например, посмотреть содержимое файла: \! cat файл.', '{"A":"Для этого служит \\g без нового запроса.","B":"Транзакцию отменяет команда SQL ROLLBACK.","C":"\\! запускает команду оболочки ОС.","D":"История выводится командой \\s."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '02.'), 'Как psql по умолчанию выполняет команды SQL с точки зрения транзакций?', '{"A":"Команды не фиксируются, пока не выполнен COMMIT","B":"Все команды сеанса выполняются в одной транзакции до выхода из psql","C":"Команды выполняются вне транзакций","D":"Каждая команда выполняется в отдельной транзакции и сразу фиксируется"}'::jsonb, 'D', 'После BEGIN в приглашении появляется звёздочка: транзакция активна.', '{"A":"Так ведёт себя только явно начатая транзакция.","B":"Общую транзакцию нужно явно начать командой BEGIN.","C":"В PostgreSQL любая команда SQL выполняется в транзакции.","D":"Это режим автофиксации (переменная AUTOCOMMIT = on)."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '03.'), 'На каких уровнях можно установить параметры конфигурации?', '{"A":"Для отдельной базы данных или пользователя","B":"Для всего экземпляра — в файлах конфигурации","C":"Для отдельной строки таблицы","D":"Для текущего сеанса"}'::jsonb, 'ABD', 'В курсе эти уровни рассматриваются в порядке от общего к частному.', '{"A":"Такие установки имеют приоритет перед файлами конфигурации.","B":"Действует для всех, если не определено иное.","C":"Параметры конфигурации на уровне строк не задаются.","D":"Командой SET или функцией set_config."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '03.'), 'Какая директива postgresql.conf подключает файлы конфигурации (с окончанием .conf) из указанного каталога?', '{"A":"`include_dir`","B":"`include_if_exists`","C":"`import_dir`","D":"`include`"}'::jsonb, 'A', 'Обычно директивы подключения располагаются в конце postgresql.conf.', '{"A":"Подключает файлы с окончанием .conf, имена которых не начинаются с точки; в Ubuntu так подключается каталог conf.d.","B":"Подключает один файл, если он существует.","C":"Такой директивы нет.","D":"Подключает один указанный файл."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '03.'), 'Чем директива include_if_exists отличается от include?', '{"A":"Отсутствие файла не считается ошибкой","B":"Читается только при запуске сервера","C":"Подключает файлы из каталога","D":"Значения из такого файла имеют наивысший приоритет"}'::jsonb, 'A', 'Если файл, подключённый через include, отсутствует, это ошибка конфигурации.', '{"A":"Файл подключается, только если существует.","B":"Все директивы обрабатываются и при перечитывании конфигурации.","C":"Это делает include_dir (только файлы с окончанием .conf).","D":"Приоритет определяется порядком чтения: побеждает последняя строка."}'::jsonb
    UNION ALL
