    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '03.'), 'В каких случаях строка в pg_file_settings будет иметь applied = false?', '{"A":"Изменение параметра требует перезапуска сервера","B":"Тот же параметр задан в строке, которая будет прочитана позже","C":"Значение совпадает со значением по умолчанию","D":"В строке есть ошибка"}'::jsonb, 'ABD', 'Представление показывает файл и номер строки, что удобно для поиска ошибок.', '{"A":"Перечитывание конфигурации такое значение не применит.","B":"Применяется значение из последней считанной строки.","C":"Совпадение со значением по умолчанию не мешает применению.","D":"В столбце error будет её описание."}'::jsonb
