    SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Страницы обычной таблицы нет в буферном кеше PostgreSQL. Где она ещё может найтись без чтения с диска?', '{"A":"В локальной памяти обслуживающего процесса","B":"В кеше операционной системы","C":"В памяти процесса postmaster","D":"В журнале предзаписи"}'::jsonb, 'B', 'Если страницы нет и в кеше ОС, её придётся прочитать с диска.', '{"A":"Там хранятся разобранные запросы, курсоры и место для сортировки, а не страницы обычных таблиц.","B":"PostgreSQL работает с диском через ОС, у которой свой кеш.","C":"Страницы данных postmaster не хранит.","D":"Журнал хранит записи об изменениях, а не страницы для чтения."}'::jsonb
) AS n(category_id, question_text, options, correct_answer, explanation, option_notes)
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NOT NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('01.', '02.', '03.', '04.'));
    IF n < 52 THEN
        RAISE EXCEPTION 'Ожидалось не меньше 52 вопросов с пояснениями в темах 01–04, найдено %', n;
    END IF;
END
$check$;

COMMIT;
